/** A domain that can be verified or approved for an organization or an enterprise. */
export interface VerifiableDomain {
  readonly createdAt: string;
  readonly databaseId: number | null;
  readonly dnsHostName: string | null;
  readonly domain: string;
  readonly hasFoundHostName: boolean;
  readonly hasFoundVerificationToken: boolean;
  readonly id: string;
  readonly isApproved: boolean;
  readonly isRequiredForPolicyEnforcement: boolean;
  readonly isVerified: boolean;
  readonly owner: Enterprise | Organization;
  readonly punycodeEncodedDomain: string;
  readonly tokenExpirationTime: string | null;
  readonly updatedAt: string;
  readonly verificationToken: string | null;
}

/** The connection type for VerifiableDomain. */
export interface VerifiableDomainConnection {
  readonly edges: ReadonlyArray<VerifiableDomainEdge | null> | null;
  readonly nodes: ReadonlyArray<VerifiableDomain | null> | null;
  readonly pageInfo: PageInfo;
  readonly totalCount: number;
}

/** An edge in a connection. */
export interface VerifiableDomainEdge {
  readonly cursor: string;
  readonly node: VerifiableDomain | null;
}

/** Autogenerated return type of VerifyVerifiableDomain. */
export interface VerifyVerifiableDomainPayload {
  readonly clientMutationId: string | null;
  readonly domain: VerifiableDomain | null;
}

/** A hovercard context with a message describing how the viewer is related. */
export interface ViewerHovercardContext {
  readonly message: string;
  readonly octicon: string;
  readonly viewer: User;
}

/** A subject that may be upvoted. */
export interface Votable {
  readonly upvoteCount: number;
  readonly viewerCanUpvote: boolean;
  readonly viewerHasUpvoted: boolean;
}

/** A workflow contains meta information about an Actions workflow file. */
export interface Workflow {
  readonly createdAt: string;
  readonly databaseId: number | null;
  readonly id: string;
  readonly name: string;
  readonly resourcePath: string;
  readonly runs: ReadonlyArray<WorkflowRun>;
  readonly state:
    | "ACTIVE"
    | "DELETED"
    | "DISABLED_FORK"
    | "DISABLED_INACTIVITY"
    | "DISABLED_MANUALLY";
  readonly updatedAt: string;
  readonly url: string;
}

/** A workflow that must run for this rule to pass */
export interface WorkflowFileReference {
  readonly path: string;
  readonly ref: string | null;
  readonly repositoryId: number;
  readonly sha: string | null;
}

/** A workflow run. */
export interface WorkflowRun {
  readonly checkSuite: CheckSuite;
  readonly createdAt: string;
  readonly databaseId: number | null;
  readonly deploymentReviews: ReadonlyArray<DeploymentReview>;
  readonly displayTitle: string | null;
  readonly event: string;
  readonly file: WorkflowRunFile | null;
  readonly id: string;
  readonly pendingDeploymentRequests: ReadonlyArray<DeploymentRequest>;
  readonly resourcePath: string;
  readonly runAttempt: number;
  readonly runNumber: number;
  readonly updatedAt: string;
  readonly url: string;
  readonly workflow: Workflow;
}

/** The connection type for WorkflowRun. */
export interface WorkflowRunConnection {
  readonly edges: ReadonlyArray<WorkflowRunEdge | null> | null;
  readonly nodes: ReadonlyArray<WorkflowRun | null> | null;
  readonly pageInfo: PageInfo;
  readonly totalCount: number;
}

/** An edge in a connection. */
export interface WorkflowRunEdge {
  readonly cursor: string;
  readonly node: WorkflowRun | null;
}

/** An executed workflow file for a workflow run. */
export interface WorkflowRunFile {
  readonly id: string;
  readonly path: string;
  readonly repositoryFileUrl: string;
  readonly repositoryName: string;
  readonly resourcePath: string;
  readonly run: WorkflowRun;
  readonly url: string;
  readonly viewerCanPushRepository: boolean;
  readonly viewerCanReadRepository: boolean;
}

/** Require all changes made to a targeted branch to pass the specified workflows before they can be merged. */
export interface WorkflowsParameters {
  readonly doNotEnforceOnCreate: boolean;
  readonly workflows: ReadonlyArray<WorkflowFileReference>;
}

